import {redirect} from "next/navigation";
import Link from "next/link";
import {Car,LayoutDashboard,MessageSquare,PlusCircle,Store,ShoppingBag} from "lucide-react";
import {requireUser} from "@/lib/auth";
import {connectMongoose} from "@/lib/db";
import {VendorProfileModel} from "@/models/VendorProfile";
export const metadata={robots:{index:false,follow:false}};
export default async function Layout({children}:{children:React.ReactNode}){const user=await requireUser("/vendor");if(user.role==="ADMIN")redirect("/admin");await connectMongoose();const profile=await VendorProfileModel.findOne({userId:user.id}).select("status displayName").lean();const approved=profile?.status==="APPROVED";const links=[{href:"/vendor",label:"Dashboard",icon:LayoutDashboard},...(approved?[{href:"/vendor/cars",label:"My cars",icon:Car},{href:"/vendor/cars/new",label:"List a new car",icon:PlusCircle},{href:"/vendor/inquiries",label:"Messages",icon:MessageSquare},{href:"/vendor/profile",label:"Profile",icon:Store}]:[{href:"/become-a-vendor",label:profile?"Application status":"Seller setup",icon:Store}]),{href:"/dashboard",label:"Switch to buying",icon:ShoppingBag}];return <div className="seller-shell"><aside className="seller-sidebar"><Link href="/vendor" className="seller-brand">CarX<span>Sailor</span></Link><nav>{links.map(({href,label,icon:Icon})=><Link href={href} key={href}><Icon size={18}/>{label}</Link>)}</nav><div className="seller-help"><b>Need help?</b><p>Our team is here to help you list and manage your cars.</p><Link href="/contact">Contact support</Link></div></aside><main className="seller-main"><header className="seller-header"><div><p className="eyebrow">SELLER WORKSPACE</p><h1>{profile?.displayName||"Seller workspace"}</h1></div>{approved&&<Link className="btn btn-dark" href="/vendor/cars/new"><PlusCircle size={17}/>List a new car</Link>}</header>{children}</main></div>}
